/// Every `pub async fn NAME(...)` inside every `impl <type_name> { ... }`
/// block in `source`, returning each method's name and its full (possibly
/// multi-line) parameter list. A type's methods no longer have to live in a
/// single `impl` block once a store is split below the module-length
/// ratchet, so this collects every occurrence rather than assuming one.
fn extract_impl_methods(source: &str, type_name: &str) -> Vec<(String, String)> {
    let impl_marker = format!("impl {type_name} {{");
    let mut methods = Vec::new();
    let mut search_from = 0;
    while let Some(offset) = source[search_from..].find(&impl_marker) {
        let impl_start = search_from + offset;
        let impl_open = impl_start + impl_marker.len() - 1;
        let impl_close = balanced_braces(source, impl_open)
            .unwrap_or_else(|| panic!("`impl {type_name}` block is never closed"));
        let impl_body = &source[impl_open..impl_close];

        let marker = "pub async fn ";
        let mut cursor = 0;
        while let Some(start) = impl_body[cursor..].find(marker) {
            let after_marker = cursor + start + marker.len();
            let name_end = impl_body[after_marker..]
                .find('(')
                .expect("a fn name is followed by (");
            let name = impl_body[after_marker..after_marker + name_end].to_string();
            let params_start = after_marker + name_end;
            let params_end = balanced_parens(impl_body, params_start)
                .unwrap_or_else(|| panic!("{type_name}::{name}'s parameter list is never closed"));
            methods.push((name, impl_body[params_start..params_end].to_string()));
            cursor = params_end;
        }
        search_from = impl_close;
    }
    methods
}

/// Every handler name passed to `get(...)` or `post(...)` on a registered
/// route. axum's `post()` builds a fresh `MethodRouter` the same way `get()`
/// does, and `.post(...)` chains a second method onto an existing one; both
/// read as the literal substring `post(` regardless of a preceding `.`.
/// Content after `#[cfg(test)]` is never scanned, since a test module's own
/// assertions (e.g. `headers().get("...")`) are not route registrations.
/// A candidate is kept only when it looks like a bare identifier or a
/// `module::function` path - this rejects a store method call like
/// `state.delegations.get(state.tenant_id.as_ref(), ...)` or a header lookup
/// like `headers.get("last-event-id")`, neither of which is a route handler.
fn extract_route_handlers(source: &str) -> Vec<String> {
    let scoped = match source.find("#[cfg(test)]") {
        Some(cut) => &source[..cut],
        None => source,
    };
    let mut handlers = Vec::new();
    for marker in ["get(", "post("] {
        let mut cursor = 0;
        while let Some(start) = scoped[cursor..].find(marker) {
            let name_start = cursor + start + marker.len();
            let name_end = scoped[name_start..]
                .find(')')
                .expect("get(...)/post(...) is closed");
            let candidate = scoped[name_start..name_start + name_end].trim();
            if looks_like_a_handler_name(candidate) {
                handlers.push(candidate.to_string());
            }
            cursor = name_start + name_end;
        }
    }
    handlers
}

/// `extract_route_handlers`, merged across every source with its own
/// router-builder function - a domain's routes no longer have to be
/// registered inline in `main.rs` once it is merged in as its own
/// sub-router.
fn extract_route_handlers_from_any(sources: &[&str]) -> Vec<String> {
    sources
        .iter()
        .flat_map(|source| extract_route_handlers(source))
        .collect()
}

/// A bare identifier, or `::`-qualified path of them - the shape of a real
/// function reference, never a method-call chain (contains a bare `.`) or a
/// string literal (contains `"`).
fn looks_like_a_handler_name(candidate: &str) -> bool {
    !candidate.is_empty()
        && candidate.split("::").all(|segment| {
            !segment.is_empty()
                && segment
                    .chars()
                    .all(|c| c.is_ascii_alphanumeric() || c == '_')
        })
}

/// The full brace-balanced body of `async fn NAME(...) ... { ... }`.
fn extract_function_body(source: &str, name: &str) -> Option<String> {
    let marker = format!("async fn {name}(");
    let start = source.find(&marker)?;
    let brace_start = source[start..].find('{')? + start;
    let end = balanced_braces(source, brace_start)?;
    Some(source[brace_start..end].to_string())
}

/// `extract_function_body`, tried against each source in turn -- a handler's
/// registration and its implementation no longer have to live in the same
/// file.
fn extract_function_body_from_any(sources: &[&str], name: &str) -> Option<String> {
    sources
        .iter()
        .find_map(|source| extract_function_body(source, name))
}

/// `extract_impl_methods`, merged across every source that carries an
/// `impl <type_name> { ... }` block for the same type -- a store's methods no
/// longer have to live in one file once it is split below the module-length
/// ratchet.
fn extract_impl_methods_from_any(sources: &[&str], type_name: &str) -> Vec<(String, String)> {
    sources
        .iter()
        .flat_map(|source| extract_impl_methods(source, type_name))
        .collect()
}

/// The index just past the `)` that matches the `(` at `open`.
fn balanced_parens(source: &str, open: usize) -> Option<usize> {
    let mut depth = 0_i32;
    for (offset, ch) in source[open..].char_indices() {
        match ch {
            '(' => depth += 1,
            ')' => {
                depth -= 1;
                if depth == 0 {
                    return Some(open + offset + 1);
                }
            }
            _ => {}
        }
    }
    None
}

/// The index just past the `}` that matches the `{` at `open`.
fn balanced_braces(source: &str, open: usize) -> Option<usize> {
    let mut depth = 0_i32;
    for (offset, ch) in source[open..].char_indices() {
        match ch {
            '{' => depth += 1,
            '}' => {
                depth -= 1;
                if depth == 0 {
                    return Some(open + offset + 1);
                }
            }
            _ => {}
        }
    }
    None
}

#[cfg(test)]
mod parser_tests {
    use super::*;

    #[test]
    fn extract_impl_methods_finds_every_method_and_its_full_signature() {
        let sample = "\
            impl Store {\n\
            \x20   pub async fn connect(url: &str) -> Result<Self, Error> { todo!() }\n\
            \x20   pub async fn scoped(\n\
            \x20       &self,\n\
            \x20       tenant_id: &str,\n\
            \x20   ) -> Result<(), Error> { todo!() }\n\
            }\n\
            impl OtherType {\n\
            \x20   pub async fn unrelated(&self) {}\n\
            }";

        let methods = extract_impl_methods(sample, "Store");

        assert_eq!(methods.len(), 2);
        assert_eq!(methods[0].0, "connect");
        assert!(!methods[0].1.contains("tenant_id"));
        assert_eq!(methods[1].0, "scoped");
        assert!(methods[1].1.contains("tenant_id: &str"));
    }

    /// A store's `impl` block can be split across multiple source files
    /// (each `include_str!`-ed separately below the module-length ratchet),
    /// so a single `source` string can legitimately carry more than one
    /// `impl <type_name> { ... }` block -- e.g. when a caller concatenates
    /// several files' text before scanning it in one pass. This must find
    /// methods in every block, not just the first.
    #[test]
    fn extract_impl_methods_finds_methods_across_several_impl_blocks_of_the_same_type() {
        let sample = "\
            impl Store {\n\
            \x20   pub async fn connect(url: &str) -> Result<Self, Error> { todo!() }\n\
            }\n\
            impl OtherType {\n\
            \x20   pub async fn unrelated(&self) {}\n\
            }\n\
            impl Store {\n\
            \x20   pub async fn scoped(&self, tenant_id: &str) -> Result<(), Error> { todo!() }\n\
            }";

        let methods = extract_impl_methods(sample, "Store");

        assert_eq!(methods.len(), 2);
        assert_eq!(methods[0].0, "connect");
        assert_eq!(methods[1].0, "scoped");
        assert!(methods[1].1.contains("tenant_id: &str"));
    }

    #[test]
    fn extract_impl_methods_from_any_merges_methods_across_separate_sources() {
        let mod_rs = "impl Store {\n    pub async fn connect(url: &str) {}\n}";
        let lease_rs = "impl Store {\n    pub async fn scoped(&self, tenant_id: &str) {}\n}";

        let methods = extract_impl_methods_from_any(&[mod_rs, lease_rs], "Store");

        assert_eq!(methods.len(), 2);
        assert_eq!(methods[0].0, "connect");
        assert_eq!(methods[1].0, "scoped");
    }

    #[test]
    fn extract_route_handlers_reads_every_get_handler_in_order() {
        let sample = "Router::new()\n\
            .route(\"/\", get(page))\n\
            .route(\"/api/v1/thing\", get(thing_handler))";

        assert_eq!(
            extract_route_handlers(sample),
            vec!["page".to_string(), "thing_handler".to_string()]
        );
    }

    /// A domain module registers a mutation route with the bare `post(...)`
    /// constructor, or chains `.post(...)` onto an existing `get(...)`
    /// route - both must be found, in the order they appear.
    #[test]
    fn extract_route_handlers_also_reads_post_handlers() {
        let sample = "Router::new()\n\
            .route(\"/things\", get(list_things).post(create_thing))\n\
            .route(\"/things/:id/archive\", post(archive_thing))";

        assert_eq!(
            extract_route_handlers(sample),
            vec![
                "list_things".to_string(),
                "create_thing".to_string(),
                "archive_thing".to_string(),
            ]
        );
    }

    /// A handler registered from a submodule keeps its `module::` qualifier
    /// - the caller strips it before looking up the function body.
    #[test]
    fn extract_route_handlers_keeps_a_submodule_qualifier() {
        let sample = "Router::new().route(\"/x\", get(page::render))";

        assert_eq!(
            extract_route_handlers(sample),
            vec!["page::render".to_string()]
        );
    }

    /// Neither a store method call (`state.store.get(state.tenant_id.as_ref(),
    /// ...)`) nor a header lookup (`headers.get("last-event-id")`) is a route
    /// registration; both must be rejected rather than mistaken for a handler.
    #[test]
    fn extract_route_handlers_rejects_a_method_call_and_a_string_literal() {
        let sample = "Router::new()\n\
            .route(\"/x\", get(real_handler))\n\
            async fn real_handler() {\n\
            \x20   let _ = state.store.get(state.tenant_id.as_ref(), &id).await;\n\
            \x20   let _ = headers.get(\"last-event-id\");\n\
            }";

        assert_eq!(
            extract_route_handlers(sample),
            vec!["real_handler".to_string()]
        );
    }

    /// A test module's own assertions (e.g. asserting on a response header
    /// via `.get(CONTENT_TYPE)`) are not route registrations and must never
    /// be scanned as one.
    #[test]
    fn extract_route_handlers_ignores_everything_after_cfg_test() {
        let sample = "Router::new().route(\"/x\", get(real_handler))\n\
            #[cfg(test)]\n\
            mod tests {\n\
            \x20   fn probe() {\n\
            \x20       let _ = response.headers().get(CONTENT_TYPE);\n\
            \x20   }\n\
            }";

        assert_eq!(
            extract_route_handlers(sample),
            vec!["real_handler".to_string()]
        );
    }

    #[test]
    fn extract_route_handlers_from_any_merges_handlers_across_separate_sources() {
        let main_rs = "Router::new().route(\"/\", get(page))";
        let domain_rs = "Router::new().route(\"/api/v1/thing\", post(create_thing))";

        assert_eq!(
            extract_route_handlers_from_any(&[main_rs, domain_rs]),
            vec!["page".to_string(), "create_thing".to_string()]
        );
    }

    #[test]
    fn extract_function_body_is_balanced_across_nested_braces() {
        let sample = "async fn handler(x: i32) -> i32 { if x > 0 { x } else { 0 } }";

        let body = extract_function_body(sample, "handler").expect("handler body found");

        assert_eq!(body, "{ if x > 0 { x } else { 0 } }");
    }

    #[test]
    fn extract_function_body_returns_none_for_a_missing_handler() {
        assert_eq!(
            extract_function_body("async fn present() {}", "absent"),
            None
        );
    }
}
